package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.rbac.domain.Role;import java.time.Instant;
public record RoleResponse(String roleId,String tenantId,String roleCode,String roleName,String description,String roleType,String status,boolean systemManaged,Instant createdAt,Instant updatedAt,long version){public static RoleResponse from(Role r){return new RoleResponse(r.roleId().value(),r.tenantId().orElse(""),r.roleCode().value(),r.roleName(),r.description(),r.roleType().name(),r.status().name(),r.systemManaged(),r.createdAt(),r.updatedAt(),r.version());}}
